// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of http.ServeMux.
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	ServeHTTP(w http.ResponseWriter, r *http.Request)
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc("GET "+options.BaseURL+"/healthz", wrapper.Health)
	m.HandleFunc("GET "+options.BaseURL+"/readyz", wrapper.Ready)
	m.HandleFunc("POST "+options.BaseURL+"/v1/barriers", wrapper.AcquireBarrier)
	m.HandleFunc("DELETE "+options.BaseURL+"/v1/barriers/{barrierId}", wrapper.ReleaseBarrier)
	m.HandleFunc("GET "+options.BaseURL+"/v1/documents", wrapper.ListDocuments)
	m.HandleFunc("POST "+options.BaseURL+"/v1/documents", wrapper.CreateDocument)
	m.HandleFunc("GET "+options.BaseURL+"/v1/documents/{documentId}/draft", wrapper.ReadDraft)
	m.HandleFunc("PUT "+options.BaseURL+"/v1/documents/{documentId}/draft", wrapper.SaveDraft)
	m.HandleFunc("GET "+options.BaseURL+"/v1/documents/{documentId}/history", wrapper.ReadRevisionHistory)
	m.HandleFunc("POST "+options.BaseURL+"/v1/documents/{documentId}/history:diff", wrapper.DiffRevisions)
	m.HandleFunc("POST "+options.BaseURL+"/v1/documents/{documentId}/history:rollback", wrapper.RollbackPublishedRevision)
	m.HandleFunc("DELETE "+options.BaseURL+"/v1/documents/{documentId}/lock", wrapper.ReleaseEditLock)
	m.HandleFunc("POST "+options.BaseURL+"/v1/documents/{documentId}/lock", wrapper.AcquireEditLock)
	m.HandleFunc("PUT "+options.BaseURL+"/v1/documents/{documentId}/lock", wrapper.RenewEditLock)
	m.HandleFunc("POST "+options.BaseURL+"/v1/documents/{documentId}/lock:force-release", wrapper.ForceReleaseEditLock)
	m.HandleFunc("PUT "+options.BaseURL+"/v1/documents/{documentId}/metadata", wrapper.UpdateDocumentMetadata)
	m.HandleFunc("GET "+options.BaseURL+"/v1/documents/{documentId}/published", wrapper.ReadPublishedRevision)
	m.HandleFunc("POST "+options.BaseURL+"/v1/documents/{documentId}:publish", wrapper.PublishDocument)
	m.HandleFunc("POST "+options.BaseURL+"/v1/documents/{documentId}:restore", wrapper.RestoreDocument)
	m.HandleFunc("POST "+options.BaseURL+"/v1/documents/{documentId}:trash", wrapper.TrashDocument)
	m.HandleFunc("POST "+options.BaseURL+"/v1/documents/{documentId}:withdraw", wrapper.WithdrawDocument)
	m.HandleFunc("GET "+options.BaseURL+"/v1/objects/{objectId}", wrapper.ReadContentObject)
	m.HandleFunc("POST "+options.BaseURL+"/v1/previews", wrapper.CreatePreviewGrant)
	m.HandleFunc("POST "+options.BaseURL+"/v1/previews:validate", wrapper.ValidatePreviewGrant)
	m.HandleFunc("GET "+options.BaseURL+"/v1/public-path:resolve", wrapper.ResolvePublicPath)
	m.HandleFunc("GET "+options.BaseURL+"/v1/public-tree", wrapper.ReadPublicTree)
	m.HandleFunc("POST "+options.BaseURL+"/v1/publications:validate", wrapper.ValidatePublications)
	m.HandleFunc("GET "+options.BaseURL+"/v1/reference-decisions/{sourceOperationId}", wrapper.ReadReferenceDecision)
	m.HandleFunc("GET "+options.BaseURL+"/v1/resource-references", wrapper.ListResourceReferences)
	m.HandleFunc("GET "+options.BaseURL+"/v1/snapshots/{snapshotId}/archive", wrapper.ReadSnapshotArchive)
	m.HandleFunc("POST "+options.BaseURL+"/v1/snapshots:discard", wrapper.DiscardSnapshot)
	m.HandleFunc("POST "+options.BaseURL+"/v1/snapshots:export", wrapper.ExportSnapshot)
	m.HandleFunc("POST "+options.BaseURL+"/v1/snapshots:stage", wrapper.StageSnapshot)
	m.HandleFunc("POST "+options.BaseURL+"/v1/trash:purge", wrapper.PurgeDocuments)
	m.HandleFunc("GET "+options.BaseURL+"/v1/tree", wrapper.ReadDocumentTree)
	m.HandleFunc("POST "+options.BaseURL+"/v1/tree:move", wrapper.MoveDocument)
	m.HandleFunc("POST "+options.BaseURL+"/v1/tree:reorder", wrapper.ReorderChildren)

	return m
}

